import {EXPEDITION_PLANS,expeditionPlan,expeditionCost} from './endgame.js';
import {roomCapacity} from './room-capacity.js';
import {pixelWorldMap} from './world-map.js';
import {SPECIES} from './world.js';
import {PRODUCTS} from './catalog.js';
import {QUALIFICATIONS,qualificationStatus,canImportLive,canSellLive,LEAGUE_CLASSES,LEAGUE_REWARDS,leagueClass,albumGoals,collectorOrders,orderCandidates,careerWeek} from './career.js';
import {OVERSEAS_REGIONS,regionGoals} from './overseas.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n.toLocaleString('ko-KR');
const button=(text,action,attrs='',kind='primary')=>`<button class="btn ${kind}" data-action="${action}" ${attrs}>${text}</button>`;
export function qualificationsScreen(s){
 return `<div class="screen-heading"><div><h2>숲지기 자격</h2><p>원정은 누구나 출발 · 생체 반입과 판매에는 자격 필요</p></div><span class="pill">누적 사육 ${s.career.reared}마리</span></div><div class="career-intro"><strong>사육 실적</strong><p>한 개체를 서로 다른 3일에 돌보면 1마리로 인정합니다. 젤리·바닥재를 같은 날 모두 바꿔도 하루 기록입니다. 실적은 판매·방생 후에도 남습니다.</p></div><div class="qualification-grid">${Object.keys(QUALIFICATIONS).map(id=>{const q=qualificationStatus(s,id);return `<section class="panel qualification-card"><div class="qualification-seal">${q.owned?'✓':'✦'}</div><h3>${q.name}</h3><p>${q.description}</p><ul>${q.requirements.map(r=>`<li class="${r.done?'met':''}"><span>${r.done?'✓':'○'} ${r.label}</span><small>${money(r.current)} / ${money(r.target)}</small></li>`).join('')}</ul>${q.owned?'<span class="qualification-owned">취득 완료 · 영구 자격</span>':button(`자격 취득 · ${money(q.fee)} 잎사귀`,'qualification-review',`data-id="${id}" ${q.eligible?'':'disabled'}`)}</section>`;}).join('')}</div><p class="career-note">국내 일반종과 완성 표본은 자격 없이 판매할 수 있습니다. 자격·비용·반입 조건은 이 게임의 진행 규칙입니다.</p>`;
}
export function forestTabs(ui){return `<nav class="commerce-tabs" aria-label="채집 메뉴">${[['forest','국내 채집'],['overseas','해외 원정']].map(([id,label])=>`<button class="commerce-tab ${ui.view===id?'active':''}" data-action="nav" data-view="${id}" ${ui.view===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`;}
function expeditionPreparation(s,ui,id,r){
 const mode=Object.hasOwn(EXPEDITION_PLANS,ui.overseasMode)?ui.overseasMode:'standard',plan=EXPEDITION_PLANS[mode],cost=expeditionCost(r,mode),target=s.inventory.overseas_hq&&r.chances[ui.overseasTarget]?ui.overseasTarget:'';
 return `<label class="field-label" for="foreign-mode">원정 방식</label><select id="foreign-mode" class="field">${Object.entries(EXPEDITION_PLANS).map(([key,p])=>`<option value="${key}" ${mode===key?'selected':''}>${p.name} · ${p.surcharge?`추가 ${money(p.surcharge)} 잎사귀`:'추가 비용 없음'}</option>`).join('')}</select><p class="trip-plan-detail">${plan.description}</p>${s.inventory.overseas_hq?`<label class="field-label" for="foreign-target">집중 채집 종 · 해외 채집 본부</label><select id="foreign-target" class="field"><option value="">현지 종 무작위</option>${Object.keys(r.chances).map(sp=>`<option value="${sp}" ${target===sp?'selected':''}>${SPECIES[sp].name}</option>`).join('')}</select><p class="trip-rule">지정하면 모든 탐사에서 선택한 종을 찾습니다.</p>`:'<p class="trip-rule">상점의 해외 채집 본부를 구매하면 현지 출현 종을 지정할 수 있어요.</p>'}<div class="trip-ticket"><div><small>선택한 원정지</small><h3>${r.name}</h3><p>${plan.name} · 왕복 여행비 ${money(r.cost)} + 특별 탐사비 ${money(plan.surcharge)}${target?`<br>집중 채집: ${SPECIES[target].name}`:''}</p></div><strong>${money(cost)} <small>잎사귀</small></strong></div><p class="trip-rule">출국·현지 이동·귀국 즉시 · 현지 탐사 최대 ${plan.surveys}회 · 대기 없음${plan.guaranteedTrait?'<br>특성 개체 보장은 6회 탐사를 모두 마친 경우 적용됩니다.':''}</p>${button(`원정 출발 · ${money(cost)} 잎사귀`,'foreign-start-review',`data-region="${id}" ${s.coins<cost?'disabled':''}`)}<details class="overseas-picker"><summary>원정지 목록 펼치기 · ${Object.keys(OVERSEAS_REGIONS).length}개 지역</summary><div class="overseas-regions">${Object.entries(OVERSEAS_REGIONS).map(([key,region])=>`<button class="location-btn ${key===id?'active':''}" data-action="foreign-region" data-region="${key}" aria-pressed="${key===id}"><strong>${region.name}</strong><small>${region.habitat}</small><span>${money(region.cost)} 잎사귀 · 즉시 도착</span></button>`).join('')}</div></details>`;
}
export function overseasScreen(s,ui,{art,traitBadges}){
 const t=s.foreignTrip,id=t?.region||ui.overseasRegion||'sumatra',r=OVERSEAS_REGIONS[id],qualified=canImportLive(s),phases={outbound:'현지로 이동 중',field:'현지 채집',surveying:'다음 탐사지로 이동 중',returning:'귀국 이동 중',arrived:'귀국 완료'};
 const plan=expeditionPlan(t||{mode:ui.overseasMode||'standard'});
 const live=t?.catches.filter(c=>c.handling==='live').length||0,space=roomCapacity(s)-s.bugs.length-s.broods.length*3-(s.auctions||[]).filter(a=>a.status==='active').reduce((n,a)=>n+(a.kind==='adult'?1:a.kind==='larva'?3:0),0);
 return `<div class="screen-heading"><div><h2>해외 원정</h2><p>${Object.keys(OVERSEAS_REGIONS).length}개 지역 · 여행비만 있으면 언제든 출발</p></div><span class="pill">${qualified?'생체 반입 가능':'표본 재료 반입 가능'}</span></div>${t?`<details class="trip-map-fold"><summary>원정 세계지도 보기</summary>${pixelWorldMap(ui,t)}</details>`:pixelWorldMap(ui)}<div class="screen-grid overseas-layout"><section class="panel"><div class="panel-head"><h3>${r.name} · ${r.habitat}</h3><span class="pill">${t?phases[t.phase]:'원정 준비'}</span></div><div class="scene-body">${t?`<div class="scene-wrap"><canvas id="scene" class="scene" width="480" height="276" role="img" aria-label="${r.name}의 원정 숲"></canvas><span class="scene-tag">${t?phases[t.phase]:'해외 현지 숲'}</span></div>`: ''}${t?`<div class="trip-status"><strong>${plan.name} · 탐사 ${t.surveys} / ${plan.surveys}회</strong><span>생체 ${live}마리 · 표본 재료 ${t.catches.length-live}점</span></div>${t.phase==='arrived'?`${button('도착한 개체 가져오기','foreign-claim',` ${live>space?'disabled':''}`)}${live>space?'<p class="trip-rule">사육실 공간을 먼저 비워 주세요.</p>':''}`:`<div class="trip-actions">${t.surveys<plan.surveys?button(`${t.surveys+1}차 현지 탐사`,'foreign-survey'):''}${button('즉시 귀국','foreign-return',`${!t.surveys||live&&!qualified||live>space?'disabled':''}`,'gold')}</div><p class="trip-rule">${!qualified&&live?'생체 반입 자격이 없습니다. 아래 개체를 표본용으로 처리한 뒤 귀국하세요.':`즉시 귀국 · 사육실 빈 공간 ${space}마리`}</p>`}<div class="trip-catches">${t.catches.map(c=>`<article class="trip-catch">${art(c.bug)}<div><strong>${esc(c.bug.name)}</strong><span>${c.bug.sex==='male'?'♂':'♀'} ${c.bug.length.toFixed(1)} mm</span>${traitBadges(c.bug)}<small>${c.handling==='live'?'현지 생체 보관':'표본용 처리 완료'}</small></div>${c.handling==='live'&&!['returning','arrived'].includes(t.phase)?button('표본용 처리','foreign-process-review',`data-id="${c.bug.id}"`,'quiet'):''}</article>`).join('')}</div>`:`${expeditionPreparation(s,ui,id,r)}`}</div></section><aside class="panel guide"><h3>이 지역의 곤충</h3><div class="overseas-species">${Object.keys(r.chances).map(sp=>`<div>${art({species:sp,sex:'male'})}<strong>${SPECIES[sp].name}</strong></div>`).join('')}</div><div class="tip">${qualified?'생체로 반입해 사육·번식·판매할 수 있습니다. 표본 제작도 가능합니다.':'자격이 없어도 원정에 갈 수 있습니다. 현지에서 표본용으로 처리한 개체만 가져올 수 있습니다.'}</div>${button('생체 자격 확인','nav','data-view="qualifications"','quiet')}<p>현지에서 처리한 개체는 보관함에서 직접 표본으로 제작해 판매하세요. 현지 보관 중 개체의 사육 상태는 유지됩니다.</p></aside></div><section class="panel regional-album"><div class="panel-head"><h3>원정지 도감</h3><span class="pill">완성 ${regionGoals(s).filter(g=>g.claimed).length} / ${Object.keys(OVERSEAS_REGIONS).length}</span></div><details><summary>지역별 수집 목표 보기</summary><div class="region-goals">${regionGoals(s).map(g=>`<div><strong>${g.name}</strong><span>${g.count} / ${g.total}종 · 방문 ${g.visits}회</span>${button(g.claimed?'보상 수령 완료':`완성 보상 ${money(Math.round(g.cost*.6))}`,'region-claim',`data-id="${g.id}" ${g.claimed||g.count!==g.total?'disabled':''}`,'quiet')}</div>`).join('')}</div></details></section>`;
}
export function leaguePanel(s,b){
 const l=s.career.league,id=b?leagueClass(b):null;
 return `<section class="panel league-panel"><div class="panel-head"><div><h3>체급별 주간 리그</h3><small>사육 ${l.week*7+1}~${l.week*7+7}일째 · 승리 3점 / 패배 1점</small></div>${id?`<span class="pill">선택 개체: ${LEAGUE_CLASSES[id].name}</span>`:''}</div><div class="league-grid">${Object.entries(LEAGUE_CLASSES).map(([key,division])=>{const score=l.classes[key]||{points:0,wins:0,played:0,claimed:[]};return `<article class="league-card ${id===key?'selected':''}"><h3>${division.name}</h3><small>${key==='light'?'40 mm 미만':key==='giant'?'95 mm 이상':`${division.min}~${division.max} mm 미만`}</small><strong class="league-score">${score.points}<small>점</small></strong><p>${score.wins}승 / ${score.played}경기</p><div>${LEAGUE_REWARDS.map(r=>button(score.claimed.includes(r.points)?`${r.points}점 수령 완료`:`${r.points}점 · ${r.coins} 잎사귀`,'league-claim',`data-division="${key}" data-points="${r.points}" ${score.points<r.points||score.claimed.includes(r.points)?'disabled':''}`,'quiet')).join('')}</div></article>`;}).join('')}</div><p class="career-note">상대는 같은 체급에서 배정됩니다. 작은 곤충도 자기 체급에서 겨룰 수 있습니다. 7일마다 점수와 보상이 갱신되고 지난 기록은 남습니다.</p>${l.history.length?`<details class="league-history"><summary>지난 리그 ${l.history.length}주 보기</summary>${l.history.map(h=>`<p>${h.week+1}주차 · ${Object.entries(h.classes).map(([key,v])=>`${LEAGUE_CLASSES[key].name} ${v.points}점`).join(' · ')}</p>`).join('')}</details>`:''}</section>`;
}
export function albumPanel(s){return `<section class="panel album-panel"><div class="panel-head"><h3>도감 수집 목표</h3></div><div class="album-goals">${albumGoals(s).map(g=>`<div><strong>${g.name}</strong><span>${g.count} / ${g.species.length}종 기록</span>${button(g.claimed?'보상 수령 완료':`완성 보상 ${money(g.coins)}`,'album-claim',`data-id="${g.id}" ${g.claimed||g.count!==g.species.length?'disabled':''}`,'quiet')}</div>`).join('')}</div></section>`;}
export function ordersScreen(s,{art}){
 return `<div class="screen-heading"><div><h2>수집가 납품 의뢰</h2><p>사육 ${careerWeek(s)*7+1}~${careerWeek(s)*7+7}일째 · 7일마다 새 의뢰</p></div></div><div class="order-grid">${collectorOrders(s).map(o=>{const candidates=orderCandidates(s,o);return `<section class="panel order-card"><h3>${o.name}</h3><p>${o.hint}</p><strong class="order-reward">${o.coins} 잎사귀 · ${o.xp} EXP</strong>${o.claimed?'<span class="qualification-owned">납품 완료</span>':`<label class="field-label" for="order-asset-${o.slot}">납품할 ${o.kind==='specimen'?'표본':'곤충'}</label><select class="field" id="order-asset-${o.slot}" data-order-for="${o.id}" ${candidates.length?'':'disabled'}>${candidates.length?candidates.map(a=>{const b=o.kind==='specimen'?a.bug:a;return `<option value="${a.id}">${esc(b.name)} · ${b.sex==='male'?'♂':'♀'} ${b.length.toFixed(1)} mm${b.favorite?' · ★ 즐겨찾기':''}</option>`;}).join(''):'<option value="">조건에 맞는 개체 없음</option>'}</select>${button('납품 확인','order-review',`data-id="${o.id}" ${candidates.length?'':'disabled'}`)}`}</section>`;}).join('')}</div><p class="career-note">납품한 개체는 수집가에게 이동합니다. 도감·후손·라인 기록은 남습니다. 해외종과 두점박이의 생체 납품에도 판매 자격이 필요합니다. 표본은 자격 없이 납품할 수 있습니다.</p>`;
}
export function equipmentNote(s,b){const family=b.species==='rhino'?'rhino':SPECIES[b.species].family||'stag',items=Object.entries(PRODUCTS).filter(([id,p])=>p.area==='equipment'&&s.inventory[id]&&(!p.species||p.species.includes(b.species))&&(!p.family||p.family===family));return items.length?`<details class="equipment-note"><summary>적용 중인 설비 ${items.length}개</summary>${items.map(([,p])=>`<p><strong>${p.name}</strong><br>${p.effect}</p>`).join('')}</details>`:'';}
